// Same parser as Case 1's reply handler - deliberately identical, because the
// forwarded payload has to be interpreted the same way by whichever system
// receives it.
const b = $json.body || $json;
const rawFrom = (b.From || b.from || '').toString();
const phone = rawFrom.replace(/^whatsapp:/i, '').replace(/[\s\-()]/g, '').trim();
let message = (b.Body || b.body || '').toString().trim();
const sid = (b.MessageSid || b.SmsMessageSid || b.SmsSid || '').toString();

// ---------------------------------------------------------------------------
// MEDIA (added 2026-08-21). A WhatsApp voice note arrives with an EMPTY Body and
// NumMedia>=1, so the old `skip = (!phone || !message)` silently dropped it here:
// the owning case never saw it, the lead got no reply, nothing was written to
// conversations, and the 48h silence clock kept running - so a lead who HAD
// answered was nudged and auto-closed for not answering. Voice notes are a
// dominant WhatsApp modality in the Gulf and Levant, so this was a real hole.
//
// Media now counts as a valid inbound. We substitute a descriptive placeholder
// for the empty body so downstream parsers, transcripts and NOT NULL columns all
// behave, and pass the media facts along for the owning case to act on.
// ---------------------------------------------------------------------------
const numMedia = parseInt((b.NumMedia || b.numMedia || '0').toString(), 10) || 0;
const mediaType = (b.MediaContentType0 || '').toString().toLowerCase();
const hasMedia = numMedia > 0;
let mediaKind = null;
if (hasMedia) {
  if (mediaType.indexOf('audio') === 0) mediaKind = 'voice';
  else if (mediaType.indexOf('image') === 0) mediaKind = 'image';
  else if (mediaType.indexOf('video') === 0) mediaKind = 'video';
  else if (mediaType.indexOf('application/pdf') === 0) mediaKind = 'document';
  else mediaKind = 'attachment';
  if (!message) {
    const label = { voice: '[voice note]', image: '[image]', video: '[video]', document: '[document]', attachment: '[attachment]' };
    message = label[mediaKind];
  }
}

const skip = (!phone || !message);

return [{ json: {
  inbound_phone: phone,
  inbound_message: message,
  inbound_sid: sid,
  has_media: hasMedia,
  media_kind: mediaKind,
  media_type: mediaType || null,
  num_media: numMedia,
  skip: skip,
  original_body: b
} }];

const inbound = $('Parse Inbound Message').first().json;

// Three lookups now. Each is fullResponse + neverError, so a failure arrives as
// a status code rather than an exception, and each is read through an explicit
// accessor because an HTTP node replaces the item it processes.
function read(resp) {
  const httpCode = (resp && resp.statusCode) ? resp.statusCode : 0;
  const body = resp ? resp.body : null;
  const ok = (httpCode === 200 && Array.isArray(body));
  return { ok: ok, code: httpCode, list: ok ? body : [],
           row: (ok && body.length) ? body[0] : null };
}
const cartR = read($('Lookup Recent Cart').first().json);
const apptR = read($('Lookup Case 3 Contact').first().json);
const wlR   = read($input.first().json);

// ---------------------------------------------------------------------------
// WHO OWNS THIS PHONE
//
// Case 2 owns it while a cart conversation is LIVE or SUPPRESSED. A finished
// cart releases the phone back to Case 1. (Unchanged from the original router.)
const CASE2_STATUSES = ['pending_verification', 'abandoned', 'recovering', 'exhausted'];

// Case 3 owns it while an appointment is LIVE - which includes 'confirmed',
// because a confirmed patient still cancels, and it includes the 24 hours AFTER
// the slot, because "sorry I missed it, can I rebook" arrives late by nature.
// An opted-out patient is also Case 3's: a repeat STOP must be swallowed by the
// system that suppressed them, never answered by another one.
const CASE3_STATUSES = ['scheduled', 'reminded_48h', 'reminded_2h', 'confirmed'];
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// PICK THE LIVE APPOINTMENT, do not trust the first row.
//
// A patient legitimately holds several: the one they cancelled on Tuesday and
// the one they booked for next month. Sorting by appointment_at and taking one
// returns whichever is EARLIEST, and after a reschedule that is frequently the
// cancelled one - at which point Case 3 releases the phone and another system
// answers a patient who is mid-conversation with the clinic.
//
// Found live on 2026-08-09: a real `توقف` was routed to Case 1 twice, because
// the sender's cancelled appointment sorted ahead of their live one. A stop
// request reaching the wrong system is a compliance failure, not a routing
// nuisance.
// ---------------------------------------------------------------------------
const CASE3_STATUSES_LIVE = CASE3_STATUSES;
function pickAppointment(list) {
  if (!list || !list.length) return null;
  // 1. A live appointment, soonest first - that is the conversation.
  const live = list.filter(function (r) {
    return CASE3_STATUSES_LIVE.indexOf(r.status) >= 0 && r.opted_out !== true;
  }).sort(function (a, b) {
    return Date.parse(a.appointment_at) - Date.parse(b.appointment_at);
  });
  if (live.length) return live[0];
  // 2. A suppressed row, so a repeat STOP is still swallowed by us.
  const supp = list.filter(function (r) { return r.opted_out === true; });
  if (supp.length) return supp[0];
  // 3. Otherwise the most recent closed row. It carries no claim, but it makes
  //    the log say WHY the phone was released rather than leaving it blank.
  return list.slice().sort(function (a, b) {
    return Date.parse(b.appointment_at) - Date.parse(a.appointment_at);
  })[0];
}

// ---------------------------------------------------------------------------
// PICK THE CART THAT OWNS THE PHONE, do not trust the first row.
//
// Exactly the pickAppointment problem, one system over. A customer legitimately
// holds several carts: the one they converted on Tuesday and the one they are
// still being messaged about. Sorting by created_at and taking ONE returns the
// newest, and that is frequently the CLOSED one - at which point Case 2 releases
// a phone it is still mid-conversation on, and another system answers.
//
// Found live on 2026-09-02: a voice note was routed to Case 1 and dropped
// because the newest of four carts was `converted_before_first_touch`, while an
// older `exhausted` cart had been sent touch 3 sixty seconds earlier. The
// compliance version is worse - an `opted_out` cart outranked by a newer closed
// cart sends a repeat STOP to a system that never suppressed the customer.
//
// This ran on `limit=1` for a month and looked correct, because until a phone
// accumulated a second cart the newest row WAS the only row.
// ---------------------------------------------------------------------------
function pickCart(list) {
  if (!list || !list.length) return null;
  // 1. A cart that still owns the conversation, most recent first.
  const live = list.filter(function (r) {
    return CASE2_STATUSES.indexOf(r.status) >= 0 && r.opted_out !== true;
  }).sort(function (a, b) {
    return Date.parse(b.created_at) - Date.parse(a.created_at);
  });
  if (live.length) return live[0];
  // 2. A suppressed cart, so a repeat STOP is still swallowed by us.
  const supp = list.filter(function (r) { return r.opted_out === true; })
    .sort(function (a, b) { return Date.parse(b.created_at) - Date.parse(a.created_at); });
  if (supp.length) return supp[0];
  // 3. Otherwise the most recent closed row. It carries no claim, but it makes
  //    the log say WHY the phone was released rather than leaving it blank.
  return list.slice().sort(function (a, b) {
    return Date.parse(b.created_at) - Date.parse(a.created_at);
  })[0];
}

const cart = pickCart(cartR.list);
const appt = pickAppointment(apptR.list);
const wl   = wlR.row;

let case3Claim = null;
if (appt) {
  if (appt.opted_out === true) case3Claim = 'appt_opted_out';
  else if (CASE3_STATUSES.indexOf(appt.status) >= 0) case3Claim = 'appt_' + appt.status;
}
if (!case3Claim && wl) case3Claim = 'waitlist_offered';

let case2Claim = null;
if (cart) {
  if (cart.opted_out === true) case2Claim = 'cart_opted_out';
  else if (CASE2_STATUSES.indexOf(cart.status) >= 0) case2Claim = 'cart_' + cart.status;
}

let target, reason;
if (case3Claim) {
  // ⚠ CASE 3 WINS A COLLISION, and the collision is logged rather than hidden.
  //
  // An unprocessed cancel costs the clinic a chair it cannot resell and leaves a
  // patient believing they cancelled. A misrouted cart reply costs one recovery
  // attempt on a cart the customer already abandoned. The two are not
  // comparable, so the tie goes to the appointment.
  target = 'case3'; reason = case3Claim;
} else if (case2Claim) {
  target = 'case2'; reason = case2Claim;
} else if (cart) {
  target = 'case1'; reason = 'cart_closed_' + cart.status;
} else {
  target = 'case1'; reason = 'no_recent_cart';
}

// Fail OPEN, unchanged in spirit: a lookup that did not answer must degrade to
// the behaviour that existed before it was added, never drop the message. A
// Case 3 lookup failure therefore falls through to the Case 1/2 logic exactly as
// it ran yesterday - and says so in the log, so a Supabase blip is never
// mistaken for "this patient has no appointment".
const lookupOk = cartR.ok && apptR.ok && wlR.ok;
if (!lookupOk && !case3Claim && !case2Claim) reason = 'router_lookup_failed';

return [{ json: {
  target: target,
  route_reason: reason,
  lookup_ok: lookupOk,
  lookup_status_code: cartR.code,
  lookup_codes: cartR.code + '/' + apptR.code + '/' + wlR.code,

  // Both claims are reported on every run, so "did these two systems ever want
  // the same phone" is answerable from run_logs instead of from memory.
  case2_claim: case2Claim,
  case3_claim: case3Claim,
  multi_case_claim: !!(case2Claim && case3Claim),

  cart_id: cart ? cart.id : null,
  cart_status: cart ? cart.status : null,
  checkout_token: cart ? cart.checkout_token : null,
  appointment_id: appt ? appt.id : null,
  appointment_status: appt ? appt.status : null,
  waitlist_id: wl ? wl.id : null,

  inbound_phone: inbound.inbound_phone,
  inbound_sid: inbound.inbound_sid,
  message_chars: inbound.inbound_message.length
} }];
